const $=s=>document.querySelector(s);
const icons=()=>window.lucide?.createIcons();
const escapeHtml=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
function readPref(key,fallback){try{return JSON.parse(localStorage.getItem(key))??fallback}catch{return fallback}}
function savePref(key,value){try{localStorage.setItem(key,JSON.stringify(value));return true}catch{return false}}
let lang=readPref('aarti-language','hi');if(!['hi','en'].includes(lang))lang='hi';
let saved=readPref('aarti-saved',[]);if(!Array.isArray(saved))saved=[];
let data=[],deity='All',savedOnly=false,active=null,textSize=readPref('aarti-size',21);if(!Number.isFinite(textSize))textSize=21;textSize=Math.max(16,Math.min(30,textSize));
const meta=[
 ['Ganesh','गणेश','जय गणेश जय गणेश देवा','Wisdom & new beginnings','#faf0df','#a66b26'],
 ['Hanuman','हनुमान','आरती कीजै हनुमान लला की','Strength & devotion','#f9e9e6','#ae5b46'],
 ['Krishna','कृष्ण','आरती कुंजबिहारी की','Love & grace','#e8f0e9','#4a7b5a'],
 ['Shiva','शिव','ॐ जय शिव ओंकारा','Stillness & surrender','#eaf0f7','#5c7b9a'],
 ['Vishnu','विष्णु','ॐ जय जगदीश हरे','Balance & compassion','#f2eaf6','#8c67a0'],
 ['Lakshmi','लक्ष्मी','ॐ जय लक्ष्मी माता','Abundance & gratitude','#fae9f0','#b16684'],
 ['Durga','दुर्गा','जय अम्बे गौरी','Courage & protection','#f9e8e9','#a75864'],
 ['Saraswati','सरस्वती','जय सरस्वती माता','Learning & creativity','#edf2ed','#627e68'],
 ['Rama','राम','आरती कीजै श्री रघुवर जी की','Dharma & devotion','#edf0fa','#727ca4'],
 ['Ganga','गंगा','ॐ जय गंगे माता','Purity & renewal','#e5f2f2','#568d8d'],
 ['Santoshi','संतोषी','जय संतोषी माता','Contentment & peace','#f7eee1','#9a774b']
];
function notify(message){$('#toast').textContent=message;$('#toast').classList.add('show');clearTimeout(notify.timer);notify.timer=setTimeout(()=>$('#toast').classList.remove('show'),2200)}
function toggleSave(id){saved=saved.includes(id)?saved.filter(x=>x!==id):[...saved,id];const persisted=savePref('aarti-saved',saved);render();if(active)updateReaderSave();notify(persisted?(saved.includes(id)?'Saved to your collection':'Removed from your collection'):'Saved for this visit; browser storage is unavailable')}
function render(){document.querySelectorAll('[data-lang]').forEach(b=>b.setAttribute('aria-pressed',b.dataset.lang===lang));$('#savedCount').textContent=saved.length;$('#savedFilter').setAttribute('aria-pressed',savedOnly);$('#filters').innerHTML=['All',...meta.map(m=>m[0])].map(name=>`<button data-deity="${name}" aria-pressed="${name===deity}">${name==='All'?'All deities':name}</button>`).join('');
const query=$('#search').value.trim().toLowerCase();let matches=data.filter(a=>(deity==='All'||a.deity===deity)&&(!savedOnly||saved.includes(a.id))&&`${a.title} ${a.hindi} ${a.deity} ${a.hi.join(' ')} ${a.en.join(' ')}`.toLowerCase().includes(query));if($('#sort').value==='az')matches.sort((a,b)=>a.title.localeCompare(b.title));
$('#resultTitle').textContent=savedOnly?'My collection':deity==='All'?'All aartis':deity+' aartis';$('#resultCount').textContent=`(${matches.length})`;$('#total').textContent=`${data.length} traditional aartis · Hindi & English script`;
$('#grid').innerHTML=matches.length?matches.map(a=>`<article class="aarti-card" style="--tint:${a.tint};--tone:${a.tone}"><button class="card-open" data-open="${a.id}" aria-label="Read ${escapeHtml(a.title)}"><span class="deity-token" aria-hidden="true">${a.symbol}</span><span class="card-deity">${a.deity} · ${a.meaning}</span><h3 class="${lang==='en'?'en-title':''}" lang="${lang}">${escapeHtml(lang==='hi'?a.hindi:a.title)}</h3><p class="card-subtitle" lang="${lang==='hi'?'en':'hi'}">${escapeHtml(lang==='hi'?a.title:a.hindi)}</p></button><button class="icon-button save-card" data-save="${a.id}" aria-label="${saved.includes(a.id)?'Unsave':'Save'} ${escapeHtml(a.title)}" title="${saved.includes(a.id)?'Remove from collection':'Save to collection'}" aria-pressed="${saved.includes(a.id)}"><i data-lucide="bookmark"></i></button><div class="card-bottom"><i data-lucide="book-open"></i><span>${a.hi.length} stanzas</span><span>Read aarti</span></div></article>`).join(''):`<div class="empty"><i data-lucide="search"></i><h3>${savedOnly&&!saved.length?'Your collection starts here':'No aartis found'}</h3><p>${savedOnly&&!saved.length?'Save a prayer with the bookmark icon.':'Try another name or clear your filters.'}</p><button id="reset">Browse all aartis</button></div>`;icons();}
function updateReaderSave(){$('#readerSave').setAttribute('aria-pressed',saved.includes(active.id));$('#readerSave').setAttribute('aria-label',saved.includes(active.id)?'Unsave aarti':'Save aarti')}
function renderReader(){if(!active)return;$('#readerDeity').textContent=active.deity+' · '+active.meaning;$('#readerTitle').textContent=lang==='hi'?active.hindi:active.title;$('#readerTitle').lang=lang;$('#readerTitle').classList.toggle('en-title',lang==='en');$('#readerSubtitle').textContent=lang==='hi'?active.title:'English transliteration · Hindi words in English script';$('#verses').lang=lang;$('#verses').style.fontSize=textSize+'px';$('#verses').innerHTML=active[lang].map((text,i)=>`<p class="verse" data-verse="${i}"><span class="verse-number">${String(i+1).padStart(2,'0')}</span>${escapeHtml(text.replace(/([,।॥])(?=[^\s,।॥])/g,'$1 '))}</p>`).join('');$('#source').href=active.url;updateReaderSave();icons()}
function openAarti(id){active=data.find(a=>a.id===id);if(!active)return;renderReader();if(!$('#reader').open)$('#reader').showModal();$('#reader').scrollTop=0;history.replaceState(null,'','#'+id)}
function closeReader(){$('#reader').close();history.replaceState(null,'','#library');active=null}
document.addEventListener('click',e=>{const b=e.target.closest('button');if(!b)return;if(b.dataset.lang){let anchor=null;if(active){const top=$('#reader').getBoundingClientRect().top;anchor=[...document.querySelectorAll('.verse')].find(v=>v.getBoundingClientRect().bottom>top+60);if(anchor)anchor={index:anchor.dataset.verse,offset:anchor.getBoundingClientRect().top};}lang=b.dataset.lang;savePref('aarti-language',lang);render();renderReader();if(anchor){const v=$(`[data-verse="${anchor.index}"]`);if(v)$('#reader').scrollTop+=v.getBoundingClientRect().top-anchor.offset;}}if(b.dataset.deity){deity=b.dataset.deity;render()}if(b.dataset.open)openAarti(b.dataset.open);if(b.dataset.save)toggleSave(b.dataset.save);if(b.id==='reset'){deity='All';savedOnly=false;$('#search').value='';render()}});
$('#search').addEventListener('input',render);$('#sort').addEventListener('change',render);$('#savedFilter').onclick=()=>{savedOnly=!savedOnly;render()};$('#savedNav').onclick=()=>{savedOnly=true;deity='All';$('#search').value='';render();$('#library').scrollIntoView()};$('#closeReader').onclick=closeReader;$('#reader').addEventListener('cancel',()=>{history.replaceState(null,'','#library');active=null});$('#reader').addEventListener('click',e=>{if(e.target===$('#reader')){const r=e.target.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)closeReader()}});$('#readerSave').onclick=()=>toggleSave(active.id);
function resize(amount){textSize=Math.min(30,Math.max(16,textSize+amount));savePref('aarti-size',textSize);$('#verses').style.fontSize=textSize+'px';$('#decrease').disabled=textSize===16;$('#increase').disabled=textSize===30}$('#decrease').onclick=()=>resize(-2);$('#increase').onclick=()=>resize(2);
fetch('lyrics.json').then(r=>{if(!r.ok)throw Error('load');return r.json()}).then(items=>{data=items.map((a,i)=>{const m=meta[i];return {...a,deity:m[0],symbol:m[1].slice(0,m[1].startsWith('श्री')?3:1),hindi:m[2],meaning:m[3],tint:m[4],tone:m[5]}});render();if(location.hash.startsWith('#aarti-'))openAarti(location.hash.slice(1))}).catch(()=>{$('#grid').innerHTML='<div class="empty"><h3>The library could not load</h3><p>Please reload to try again.</p><button onclick="location.reload()">Reload library</button></div>'});icons();
